/* eslint-env node */
/**
 * v15.7.2 self-audit: several industries must actually reach DIFFERENT sections.
 *
 * Run:  node tests/js/test-industry-rotation.js      (exit 0 = pass, 1 = fail)
 *
 * The first build of this release told every section "set each scenario in ONE of these
 * industries and vary it across slides". Sections are generated by independent calls, so
 * that instruction, given identically to every call, cannot make them vary. The
 * independent review caught it. Each section is now given one industry in turn
 * (prompts.js ccSectionContext, generator.js _industrySlot). This asserts it on the REAL
 * user prompt the vendor receives, built by the real prompts.js.
 *
 * @package    mod_contentcreator
 * @copyright  2026 LMS-Labs
 * @license    http://www.gnu.org/copyleft/gpl.html GNU GPL v3 or later
 */

'use strict';

const fs = require('fs');
const path = require('path');
const vm = require('vm');

const ROOT = path.resolve(__dirname, '..', '..');
const SRC = path.join(ROOT, 'amd', 'src');

let failures = 0;
let checks = 0;
/**
 * @param {String} label
 * @param {Boolean} ok
 * @param {String} [detail]
 */
function check(label, ok, detail) {
    checks++;
    if (ok) { console.log('  ok   ' + label); return; }
    failures++;
    console.log('  FAIL ' + label + (detail ? '\n         ' + detail : ''));
}

/**
 * @param {String} file
 * @param {Array} deps
 * @return {Object}
 */
function loadAmd(file, deps) {
    const sandbox = {define: function(d, f) { sandbox._m = f.apply(null, deps || []); },
        window: {}, document: {}, console: console, M: {cfg: {}}, setTimeout: setTimeout};
    vm.createContext(sandbox);
    vm.runInContext(fs.readFileSync(path.join(SRC, file), 'utf8'), sandbox, {filename: file});
    return sandbox._m;
}
const CcState = loadAmd('cc-state.js');
const Legislation = loadAmd('legislation.js');
const CardQuality = loadAmd('card-quality.js', [CcState]);
const Prompts = loadAmd('prompts.js', [Legislation, CcState, CardQuality]);

check('prompts.js exports ccSectionContext', typeof Prompts.ccSectionContext === 'function');

const base = {
    mode: 'vet', country: 'AU', state: 'WA', language: 'en-AU', jobLevel: 'Worker / Operator',
    unitCode: 'CPCWHS1001', unitTitle: 'Prepare to work safely',
    industry: 'Construction, Mining', industrySector: 'Civil, Underground',
    industries: ['Construction', 'Mining'], industrySectors: ['Civil', 'Underground'],
    industryMap: {Construction: ['Civil'], Mining: ['Underground']},
    industryContext: 'Multiple industries - ...: Construction (Civil); Mining (Underground)'
};
const sec = function(slot, title) {
    return {id: 's' + slot, title: title, _sectionIndex: slot, _industrySlot: slot,
        _siblingTitles: ['Hazards', 'Controls', 'Reporting']};
};

console.log('\n1. Two industries, three sections');
const prompts = [0, 1, 2].map(function(i) {
    return Prompts.buildFiveCardUserPrompt(base, sec(i, ['Hazards', 'Controls', 'Reporting'][i]));
});
const industryLine = function(p) { return (p.match(/- Industry: ([^\n]*)/) || [])[1] || ''; };
check('section 1 is set in Construction (Civil)', /^Construction - Civil\. Set this slide's scenarios in Construction/.test(industryLine(prompts[0])),
    industryLine(prompts[0]));
check('section 2 is set in Mining (Underground)', /^Mining - Underground\. Set this slide's scenarios in Mining/.test(industryLine(prompts[1])),
    industryLine(prompts[1]));
check('section 3 wraps back to Construction', /^Construction - Civil\./.test(industryLine(prompts[2])),
    industryLine(prompts[2]));
check('each section is told what the rest of the course covers',
    /also covers Mining/.test(industryLine(prompts[0])) && /also covers Construction/.test(industryLine(prompts[1])));
check('no section gets the other industry\'s sub-industry',
    !/Underground/.test(industryLine(prompts[0]).split('. Set')[0])
    && !/Civil/.test(industryLine(prompts[1]).split('. Set')[0]));

console.log('\n2. One industry: the prompt is exactly what v15.7.1 produced');
const one = Object.assign({}, base, {industry: 'Construction', industrySector: 'Civil',
    industries: ['Construction'], industrySectors: ['Civil'], industryMap: {Construction: ['Civil']},
    industryContext: 'Construction - Civil'});
const oneSec = sec(1, 'Controls');
const legacy = Object.assign({}, one);
delete legacy.industries; delete legacy.industrySectors; delete legacy.industryMap;
const legacySec = Object.assign({}, oneSec);
delete legacySec._industrySlot;
check('one industry gives the same prompt as a pre-15.7.2 context',
    Prompts.buildFiveCardUserPrompt(one, oneSec) === Prompts.buildFiveCardUserPrompt(legacy, legacySec));
check('ccSectionContext returns the context untouched for one industry',
    Prompts.ccSectionContext(one, oneSec) === one);
check('...and for a section with no slot (repair passes)',
    Prompts.ccSectionContext(base, legacySec) === base);

console.log('\n3. The same rotation reaches the Workplace and Policy routes');
const wp = Object.assign({}, base, {mode: 'workplace', companyName: 'Acme'});
check('workplace section 2 is set in Mining',
    /Set this slide's scenarios in Mining/.test(Prompts.buildFiveCardUserPrompt(wp, sec(1, 'Controls'))));
const pol = Object.assign({}, base, {mode: 'policy', policyMeta: {title: 'Incident Policy'}});
const polPrompt = Prompts.buildFiveCardUserPrompt(pol, sec(1, 'Controls'));
check('policy prompts build without error with several industries', typeof polPrompt === 'string' && polPrompt.length > 100);

console.log('\n4. generator.js numbers sections across the WHOLE pack');
const gen = fs.readFileSync(path.join(SRC, 'generator.js'), 'utf8');
check('one running slot outside the topic loop, stamped on every section',
    /let _industrySlot = 0;\s*\n\s*for \(const topic of topics\)/.test(gen)
    && /s\._industrySlot = _industrySlot\+\+;/.test(gen));
const builder = fs.readFileSync(path.join(SRC, 'builder.js'), 'utf8');
check('both VET and Workplace contexts carry industryMap',
    (builder.match(/industryMap: ccIndustryMap\(/g) || []).length === 2);

console.log('\n5. The repair pass and the image request get the SAME section industry');
check('generator.js builds the repair prompt from ccSectionContext',
    /buildContentRepairPromptForMode\(lastScore\?\.cards \|\| \[\], topIssues, topicTitle,\s*Prompts\.ccSectionContext\(promptContext, topic\)\)/.test(gen));
check('generator.js requests the slide image with ccSectionContext',
    /generateTopicImage\(enrichedSection,\s*Prompts\.ccSectionContext\(plannedManifest\.context, section\), cmid\)/.test(gen));
const repair = Prompts.buildContentRepairPromptForMode([{cardType: 'hook-scenario'}],
    [{issue: 'too short'}], 'Controls', Prompts.ccSectionContext(base, sec(1, 'Controls')));
check('a Mining slide\'s repair prompt names Mining\'s sub-industry, not Construction\'s',
    /Industry: Underground/.test(repair) && !/Industry: Civil/.test(repair) && !/Construction, Mining/.test(repair),
    (repair.match(/Industry: [^\n]*/) || [''])[0]);
const wpRepair = Prompts.buildContentRepairPromptForMode([{cardType: 'hook-scenario'}],
    [{issue: 'too short'}], 'Controls', Prompts.ccSectionContext(Object.assign({}, base, {mode: 'workplace'}), sec(0, 'Hazards')));
check('...and on the Workplace route', /Industry: Civil/.test(wpRepair), (wpRepair.match(/Industry: [^\n]*/) || [''])[0]);
check('each slide is told to translate a role from another industry to its own',
    /use their nearest equivalent in Mining/.test(industryLine(prompts[1])));

console.log('\n' + (failures ? 'FAILED ' + failures + ' of ' + checks : 'PASSED all ' + checks + ' rotation checks'));
process.exit(failures ? 1 : 0);
